#!/usr/bin/env bash
# Regenerates the Swift bindings over crates/codewire-client-ffi (#3825):
# Sources/CodewireClientFFI/codewire_client_ffi.swift, and the header and
# module map in FFI/include that the xcframework carries. They are generated by
# the crate's own check (src/swift_bindings_tests.rs), which CI runs to fail on
# any difference, so this works on any host with Rust; no iOS SDK is needed.
#
# usage: apps/ios/scripts/generate-bindings.sh
set -euo pipefail

ROOT="$(cd "$(dirname "${BASH_SOURCE[0]}")/../../.." && pwd)"
cd "$ROOT"
UPDATE_SWIFT_BINDINGS=1 cargo test --locked -p codewire-client-ffi --features bindgen --lib \
  swift_bindings_tests::
git status --short -- apps/ios/Sources/CodewireClientFFI apps/ios/FFI
